import "pe"
rule x86_xorshift_login_columns_prefix {
  strings:
    $call_ebp8 = { 68 [4] 8D 4D ?? E8 ?? ?? ?? ?? }
    $call_ebp32 = { 68 [4] 8D 8D [4] E8 ?? ?? ?? ?? }
    $call_esp8 = { 68 [4] 8D 4C 24 ?? E8 ?? ?? ?? ?? }
  condition:
    pe.is_pe and filesize < 16MB and any of ($call_*) and
    for any section in (0..pe.number_of_sections-1) : (
      pe.sections[section].characteristics & pe.SECTION_MEM_EXECUTE != 0 and
      pe.sections[section].raw_data_size >= 16 and
    for any c in (pe.sections[section].raw_data_offset+11..pe.sections[section].raw_data_offset+pe.sections[section].raw_data_size-5) : (
      uint8(c) == 0xe8 and
      ((uint8(c-8) == 0x68 and uint16(c-3) == 0x4d8d) or
       (uint8(c-11) == 0x68 and uint16(c-6) == 0x8d8d) or
       (uint8(c-9) == 0x68 and uint16(c-4) == 0x4c8d and uint8(c-2) == 0x24)) and
      with target = c+5+int32(c+1) : (
        target >= pe.sections[section].raw_data_offset and target+768 < filesize and
        for any k in (target..target+768) : (
          k+43 <= pe.sections[section].raw_data_offset+pe.sections[section].raw_data_size and
          uint32(k) == 0x3779b9b8 and uint8(k+4) == 0x9e and
          uint8(k+9) == 0xb8 and uint32(k+10) == 0x7f4a7c15 and
          (uint16(k+20) == 0xc781 or uint16(k+20) == 0xc681) and
          uint8(k+28) == 0x81 and (uint8(k+29) == 0xd3 or uint8(k+29) == 0xd7) and
          uint16(k+36) == 0xa40f and uint8(k+39) == 13 and uint8(k+42) == 13 and
          with seed = uint16(k+22) : (
            for any base in (c-768..c-12) : (
              base >= pe.sections[section].raw_data_offset and (
                (
                  uint8(c-8) == 0x68 and uint16(c-3) == 0x4d8d and uint16(base) == 0x45c7 and uint8(base+2) == uint8(c-1) and
                  for all j in (0..7) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6f205443454c4553 >> ((j-0)*8)) & 255)
                    )
                  )
                  and for all j in (8..15) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x72755f6e69676972 >> ((j-8)*8)) & 255)
                    )
                  )
                  and for all j in (16..23) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6e72657375202c6c >> ((j-16)*8)) & 255)
                    )
                  )
                  and for all j in (24..31) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f656d61 >> ((j-24)*8)) & 255)
                    )
                  )
                  and for all j in (32..39) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x7773736170202c65 >> ((j-32)*8)) & 255)
                    )
                  )
                  and for all j in (40..47) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 3 + (j\4)*7 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f64726f >> ((j-40)*8)) & 255)
                    )
                  )
                )
                or (
                  uint8(c-11) == 0x68 and uint16(c-6) == 0x8d8d and uint16(base) == 0x85c7 and int32(base+2) == int32(c-4) and
                  for all j in (0..7) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6f205443454c4553 >> ((j-0)*8)) & 255)
                    )
                  )
                  and for all j in (8..15) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x72755f6e69676972 >> ((j-8)*8)) & 255)
                    )
                  )
                  and for all j in (16..23) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6e72657375202c6c >> ((j-16)*8)) & 255)
                    )
                  )
                  and for all j in (24..31) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f656d61 >> ((j-24)*8)) & 255)
                    )
                  )
                  and for all j in (32..39) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x7773736170202c65 >> ((j-32)*8)) & 255)
                    )
                  )
                  and for all j in (40..47) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 6 + (j\4)*10 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f64726f >> ((j-40)*8)) & 255)
                    )
                  )
                )
                or (
                  uint8(c-9) == 0x68 and uint16(c-4) == 0x4c8d and uint8(c-2) == 0x24 and uint16(base) == 0x44c7 and uint8(base+2) == 0x24 and uint8(base+3)+4 == uint8(c-1) and
                  for all j in (0..7) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6f205443454c4553 >> ((j-0)*8)) & 255)
                    )
                  )
                  and for all j in (8..15) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x72755f6e69676972 >> ((j-8)*8)) & 255)
                    )
                  )
                  and for all j in (16..23) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6e72657375202c6c >> ((j-16)*8)) & 255)
                    )
                  )
                  and for all j in (24..31) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f656d61 >> ((j-24)*8)) & 255)
                    )
                  )
                  and for all j in (32..39) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x7773736170202c65 >> ((j-32)*8)) & 255)
                    )
                  )
                  and for all j in (40..47) : (
                    with state = seed + j*0x7c15 : (
                      (uint8(base + 4 + (j\4)*8 + j%4) ^
                       ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f64726f >> ((j-40)*8)) & 255)
                    )
                  )
                )
                or (
                  uint8(c-8) == 0x68 and uint16(c-3) == 0x4d8d and uint16(base) == 0x45c7 and uint8(base+2) == uint8(c-1) and uint8(base+2) < 128 and
                  for all j in (0..7) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6f205443454c4553 >> ((j-0)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6f205443454c4553 >> ((j-0)*8)) & 255))
                      )
                    )
                  )
                  and for all j in (8..15) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x72755f6e69676972 >> ((j-8)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x72755f6e69676972 >> ((j-8)*8)) & 255))
                      )
                    )
                  )
                  and for all j in (16..23) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6e72657375202c6c >> ((j-16)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x6e72657375202c6c >> ((j-16)*8)) & 255))
                      )
                    )
                  )
                  and for all j in (24..31) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f656d61 >> ((j-24)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f656d61 >> ((j-24)*8)) & 255))
                      )
                    )
                  )
                  and for all j in (32..39) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x7773736170202c65 >> ((j-32)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x7773736170202c65 >> ((j-32)*8)) & 255))
                      )
                    )
                  )
                  and for all j in (40..47) : (
                    with state = seed + j*0x7c15 : (
                      with short = (131-uint8(base+2))\4 : (
                        ((j\4) < short and (uint8(base+3+(j\4)*7+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f64726f >> ((j-40)*8)) & 255)) or
                        ((j\4) >= short and (uint8(base+6+(j\4)*10-short*3+j%4) ^ ((state ^ (state >> 7) ^ (state << 6)) & 255)) == ((0x756c61765f64726f >> ((j-40)*8)) & 255))
                      )
                    )
                  )
                )
              )
            )
          )
        )
      )
    )
    )
}

rule x86_winexec_hash_launch {
  strings:
    $call = { BA 98 FE 8A 0E 52 50 E8 ?? ?? ?? ?? }
    $exe = /[a-z0-9_.-]{1,32}\.exe/ nocase
  condition:
    all of them
}
